public static int getSandiumOpaqueStatusColor(int color) {
    int alpha = Color.alpha(color);
    if (alpha == 255) return color;
    int inverse = 255 - alpha;
    int red = (Color.red(color) * alpha + 18 * inverse + 127) / 255;
    int green = (Color.green(color) * alpha + 18 * inverse + 127) / 255;
    int blue = (Color.blue(color) * alpha + 18 * inverse + 127) / 255;
    return Color.rgb(red, green, blue);
}

